using SignalCluster.Core; using Xunit; public class SignalAlgorithmsTests { [Fact] public void Gcd(){Assert.Equal(6,SignalAlgorithms.GreatestCommonDivisor(54,24));} [Fact] public void Sort(){Assert.Equal(new[]{1,2,3,4},SignalAlgorithms.MergeSort(new[]{4,1,3,2}));} [Fact] public void FftDc(){var m=SignalAlgorithms.FftMagnitude(new[]{1d,1d,1d,1d});Assert.Equal(4,m[0],8);Assert.Equal(0,m[1],8);} [Fact] public void DispersionPositive(){Assert.True(SignalAlgorithms.DispersionDelayMilliseconds(10,400,800)>0);} }